from math import gcd
from functools import reduce

def find_wcd(n, pairs):
    def is_valid_wcd(x):
        return any(a % x == 0 or b % x == 0 for a, b in pairs)

    def gcd_of_list(lst):
        return reduce(gcd, lst)

    # Extract all numbers from pairs
    all_numbers = [a for a, b in pairs] + [b for a, b in pairs]

    # Find the GCD of all numbers
    overall_gcd = gcd_of_list(all_numbers)

    # If the GCD is 1, there is no WCD greater than 1
    if overall_gcd == 1:
        return -1

    # Binary search for the WCD
    low, high = 2, overall_gcd
    while low < high:
        mid = (low + high + 1) // 2
        if is_valid_wcd(mid):
            low = mid
        else:
            high = mid - 1

    return low if is_valid_wcd(low) else -1

